read* DoMakeServerThread();		// Make a new server thread to handle the requested connection. 		// Override to make a subclass of CServerThread for the specific protocol. 	virtual void StartServer(CServerThread* server);		// Start a server thread. 	//------------------------------------------------------------------------------------	// Data	//------------------------------------------------------------------------------------protected:	CInetAddress	fLocalAddress;	CTCPEndpoint	fEndpoint;};#endif // __CListenerThread__